async function api(path,body){
 let response;
 try{response=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});}
 catch{const error=new Error(body?'ยังยืนยันผลไม่ได้ ลองส่งคำขอเดิมอีกครั้ง':'เชื่อมต่อระบบไม่สำเร็จ กรุณาลองใหม่');error.uncertain=!!body;throw error;}
 const data=await response.json().catch(()=>({error:'ไม่สามารถอ่านคำตอบจากระบบได้'}));
 if(!response.ok){const error=new Error(data.error||'ดำเนินการไม่สำเร็จ กรุณาลองใหม่');error.status=response.status;error.uncertain=!!body&&response.status>=500;throw error;}
 return data;
}
const companyQuery='?company_id='+encodeURIComponent(companyId);
async function refresh(){state=await api(publicToken?'/api/first-aid/public/'+encodeURIComponent(publicToken):'/api/first-aid/state'+companyQuery);staleData=false;return state;}
async function saveAction(body){const result=await api('/api/first-aid/manage'+companyQuery,body);try{await refresh();}catch{staleData=true;}return result;}
async function saveTransaction(body,idempotencyKey){const result=await api('/api/first-aid/transactions'+companyQuery,{...body,idempotencyKey});try{await refresh();}catch{staleData=true;}return result;}
async function submitPublicIssue(body,idempotencyKey){
 if(!publicToken)throw new Error('กรุณาเปิดจากลิงก์หรือ QR ประจำจุด');
 const result=await api('/api/first-aid/public/'+encodeURIComponent(publicToken),{...body,kind:'issue',idempotencyKey});
 try{await refresh();}catch{}return result.events;
}
