function overview(){
 const s=stats(state,scope),needs=s.locationCount-s.readyLocations;if(!s.locationCount)return `${header('เริ่มดูแลจุดปฐมพยาบาล','สร้างจุดจัดเก็บและรายการยา แล้วรับเข้าตามจำนวนที่ตรวจนับจริง','FIRST AID WORKSPACE',button('เพิ่มจุดปฐมพยาบาล','newlocation','cross','primary'))}<section class="panel"><div class="empty">${icon('bag')}<h3>ยังไม่มีจุดปฐมพยาบาลของบริษัทนี้</h3><p>เริ่มจากตู้ยา กล่อง กระเป๋าฉุกเฉิน หรือห้องพยาบาล</p>${button('สร้างจุดแรก','newlocation','cross','primary')}</div></section>`;
 const low=scopedLocations().flatMap(l=>locationStatus(state,l.id).lowItems.map(item=>({l,item})));
 const expired=scopedLots().filter(l=>l.expiry&&expiryDays(l.expiry,state.asOf)<0),near=scopedLots().filter(l=>{const d=l.expiry?expiryDays(l.expiry,state.asOf):Infinity;return d>=0&&d<=90;});
 const overdue=scopedLocations().filter(l=>locationStatus(state,l.id).overdue);
 const pending=pendingExpiryLots(state,null,scope);
 const refillSource=low.length?state.locations.find(l=>l.id!==low[0].l.id&&itemBalance(state,low[0].item.id,l.id)>0):null;
 const refillAction=low.length?(refillSource?`record:transfer:${low[0].item.id}:${refillSource.id}:${low[0].l.id}`:`record:receive:${low[0].item.id}:${low[0].l.id}`):'';
 const issues=scopedLocations().filter(l=>l.inspectionIssue);const unconfigured=scopedLocations().filter(l=>locationStatus(state,l.id).unconfigured);
 const rows=[...(pending.length?[['','calendar',`รอยืนยันวันหมดอายุ ${pending.length} ล็อต`,`${itemBy(pending[0].itemId).name} · แยกจากยอดพร้อมใช้จนกว่าจะตรวจบรรจุภัณฑ์`,'ตรวจสอบ',`detail:${pending[0].itemId}`]]:[]),...(unconfigured.length?[['blue','box',`กำหนดรายการประจำจุด ${unconfigured.length} จุด`,`${unconfigured[0].name} · ยังไม่ได้กำหนดเกณฑ์ขั้นต่ำ`,'ตั้งค่ารายการ',`thresholds:${unconfigured[0].id}`]]:[]),...(issues.length?[['red','alert',`ผลตรวจพบปัญหา ${issues.length} จุด`,`${issues[0].name} · ตรวจรายละเอียดและแก้ไขก่อนตรวจซ้ำ`,'ตรวจจุด',`inspect:${issues[0].id}`]]:[]),...(expired.length?[['red','alert',`พบเวชภัณฑ์หมดอายุ ${expired.length} ล็อต`,`${itemBy(expired[0].itemId).name} · ${locBy(expired[0].locationId).name}`,'ตรวจสอบ',`detail:${expired[0].itemId}`]]:[]),...(low.length?[['','box',`เติมของต่ำกว่าเกณฑ์ ${new Set(low.map(x=>x.item.id)).size} รายการ`,`${low.slice(0,2).map(x=>x.item.name).join(', ')} · ${low[0].l.name}`,'เติมสต็อก',refillAction]]:[]),...(near.length?[['','calendar',`ใกล้หมดอายุใน 90 วัน ${near.length} ล็อต`,`${itemBy(near[0].itemId).name} · หมดอายุ ${date(near[0].expiry)}`,'ดูรายการ','expiry']]:[]),...(overdue.length?[['blue','clock','มีจุดที่ถึงรอบตรวจความพร้อม',`${overdue[0].name} · ตรวจล่าสุด ${overdue[0].lastChecked?date(overdue[0].lastChecked):'ยังไม่เคยตรวจ'}`,'ตรวจจุด',`inspect:${overdue[0].id}`]]:[])];
 return `${header('พร้อมดูแล ในทุกวัน','ดูความพร้อมของจุดปฐมพยาบาล และจัดการสิ่งสำคัญได้จากที่เดียว','YOUR CARE WORKSPACE',button('ดูรายงาน','nav:reports','chart','ghost')+button('บันทึกการใช้','record:issue','cross','primary'))}<section class="intro-grid" aria-label="สรุปความพร้อม"><div class="readiness-card"><div><div class="overline">${icon('shield')} ความพร้อมของจุดปฐมพยาบาล</div><h2>${needs?`อีก ${n(needs)} จุด ที่ต้องดูแล`:'ทุกจุดพร้อมดูแล'}</h2><p>${needs?'เติมสิ่งที่ขาด ตรวจสิ่งที่ใกล้ถึงรอบ':'ยาและเวชภัณฑ์เพียงพอ และตรวจตามรอบแล้ว'}</p><button class="btn text" data-action="nav:locations">ดูจุดปฐมพยาบาลทั้งหมด ${icon('arrow')}</button></div><div class="readiness-ring" style="--value:${(s.locationCount?s.readyLocations/s.locationCount*100:0)}%"><div class="ring-number">${n(s.readyLocations)}<span> / ${n(s.locationCount)}</span><small>จุดพร้อมใช้</small></div></div></div><div class="metrics"><div class="metric"><span class="metric-label">ยาและเวชภัณฑ์</span><b class="metric-value">${n(s.itemCount)}</b><span class="metric-note">รายการในระบบ</span><span class="metric-icon">${icon('box')}</span></div><div class="metric alert"><span class="metric-label">ต่ำกว่าเกณฑ์</span><b class="metric-value">${n(s.lowStockItems)}</b><span class="metric-note">รายการที่ต้องเติมในแต่ละจุด</span><span class="metric-icon">${icon('alert')}</span></div><div class="metric alert"><span class="metric-label">ใกล้หมดอายุ</span><b class="metric-value">${n(s.nearExpiryLots)}</b><span class="metric-note">ล็อต ภายใน 90 วัน</span><span class="metric-icon">${icon('calendar')}</span></div><div class="metric"><span class="metric-label">การจ่ายใช้เดือนนี้</span><b class="metric-value">${n(s.monthUses)}</b><span class="metric-note">รายการ · ${monthLabel()}</span><span class="metric-icon">${icon('out')}</span></div></div></section><div class="content-grid"><section class="panel"><div class="panel-header"><div><div class="panel-title"><h2>สิ่งที่ต้องจัดการ</h2><span class="count">${rows.length}</span></div><p class="panel-subtitle">เรียงสิ่งสำคัญ เพื่อให้ทุกจุดพร้อมใช้งาน</p></div>${icon('shield')}</div><div class="attention-list">${rows.length?rows.map(([color,ic,title,sub,action,code])=>`<div class="attention-row"><div class="attention-icon ${color}">${icon(ic)}</div><div class="attention-info"><b>${title}</b><p>${esc(sub)}</p></div>${button(action,code)}</div>`).join(''):`<div class="empty">${icon('checkCircle')}<h3>จัดการครบแล้ว</h3><p>ทุกจุดในพื้นที่ที่เลือกพร้อมใช้งาน</p></div>`}</div><div class="panel-footer"><span>เกณฑ์ขั้นต่ำแยกตามจุด · ตรวจความพร้อมทุก 30 วัน</span><span>อัปเดตจากรายการล่าสุด</span></div></section><div class="right-column"><section class="panel quick-panel"><div class="panel-header"><h2>ทำรายการด่วน</h2><span class="muted small">QUICK ACTIONS</span></div><div class="quick-actions"><button class="quick-action" data-action="record:receive">${icon('in')}รับเข้าสินค้า</button><button class="quick-action" data-action="record:transfer">${icon('transfer')}โอนเติมจุด</button><button class="quick-action" data-action="nav:locations">${icon('checkCircle')}ตรวจความพร้อม</button></div></section><section class="panel activity-panel"><div class="panel-header"><h2>ความเคลื่อนไหวล่าสุด</h2><button class="btn text" data-action="nav:history">ดูทั้งหมด ${icon('arrow')}</button></div><div class="activity-list">${scopedEvents().slice(0,3).map(e=>`<div class="activity-row"><div class="activity-dot"></div><div class="activity-copy"><b>${kinds[e.kind]} ${esc(itemBy(e.itemId)?.name)} ${n(e.quantity)} ${esc(itemBy(e.itemId)?.unit)}</b><p>${esc(locBy(e.locationId)?.name)}${e.destinationId?` → ${esc(locBy(e.destinationId)?.name)}`:''}</p></div><span class="activity-time">${eventDate(e,false)}</span></div>`).join('')}</div></section></div></div><div class="section-heading"><h2>จุดปฐมพยาบาลในพื้นที่</h2><button class="btn text" data-action="nav:locations">ดูทั้ง ${s.locationCount} จุด ${icon('arrow')}</button></div><div class="location-strip">${scopedLocations().slice(0,3).map(l=>{const st=locationStatus(state,l.id);return `<button class="location-mini" data-action="location:${l.id}"><span class="place-icon">${itemIcon(l)}</span><span><b>${esc(l.name)}</b><small><i class="status-dot ${st.ready?'':st.expiredLots.length?'red':'orange'}"></i>${st.ready?'พร้อมใช้งาน':st.expiredLots.length?'พบของหมดอายุ':st.pendingLots.length?'รอยืนยันวันหมดอายุ':st.hasIssue?'มีปัญหาจากผลตรวจ':st.unconfigured?'ยังไม่กำหนดรายการ':st.lowItems.length?`ต้องเติม ${st.lowItems.length} รายการ`:'ถึงรอบตรวจ'} · ${esc(l.type)}</small></span></button>`;}).join('')}</div>`;
}
function matches(item){return `${esc(item.name)} ${esc(item.generic)} ${esc(item.category)} ${item.id}`.toLowerCase().includes(query.toLowerCase());}
function itemStatus(item){if(scope!=='all')return getItemStatus(state,item,scope);const balance=itemBalance(state,item.id);if(pendingExpiryLots(state,item.id).length)return {key:'warn',label:'รอยืนยันวันหมดอายุ',balance};if(balance===0)return {key:'out',label:state.lots.some(l=>l.itemId===item.id)?'หมด':'ยังไม่รับเข้า',balance};const statuses=state.thresholds.filter(t=>t.itemId===item.id).map(t=>getItemStatus(state,item,t.locationId));const hasLow=statuses.some(x=>x.key!=='ok');return {key:hasLow?'low':'ok',label:hasLow?'มีจุดต้องเติม':'เพียงพอ',balance};}
function inventory(){
 let rows=state.items.filter(matches).filter(item=>scope==='all'||state.lots.some(l=>l.itemId===item.id&&l.locationId===scope));
 rows=rows.filter(item=>filter==='all'||(filter==='low'?itemStatus(item).key!=='ok':filter==='expiry'?scopedLots().some(l=>l.itemId===item.id&&l.expiry&&expiryDays(l.expiry,state.asOf)<=90):item.category===filter));
 return `${header('ยาและเวชภัณฑ์','รู้จำนวนพร้อมใช้ ดูวันหมดอายุ และเติมสต็อกในจุดที่ต้องการ','INVENTORY',button('เพิ่มรายการ','newitem','cross')+button('ส่งออก','export:stock','download')+button('รับเข้าสินค้า','record:receive','cross','primary'))}<div class="toolbar"><label class="search">${icon('search')}<input id="search" type="search" placeholder="ค้นหาชื่อยา เวชภัณฑ์ หรือรหัสรายการ" value="${esc(query)}" aria-label="ค้นหาสต็อก"></label><div class="toolbar-right"><span class="muted small">${rows.length} รายการ</span><select class="select" id="category" aria-label="กรองหมวดหมู่"><option value="all">ทุกหมวดหมู่</option>${['ยา','เวชภัณฑ์','อุปกรณ์'].map(c=>`<option ${filter===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div></div><div class="tabs" role="tablist" aria-label="สถานะสต็อก">${[['all','ทั้งหมด'],['low','ต้องเติม'],['expiry','ใกล้หมดอายุ / หมดอายุ']].map(([id,text])=>`<button class="tab ${filter===id?'active':''}" role="tab" aria-selected="${filter===id}" data-filter="${id}">${text}</button>`).join('')}</div><section class="panel"><div class="table-scroll"><table class="inventory-table stock-table"><thead><tr><th>รายการ</th><th>หมวดหมู่</th><th class="num">พร้อมใช้</th><th>หมดอายุเร็วสุด</th><th>สถานะ</th><th><span class="small">รายละเอียด</span></th></tr></thead><tbody>${rows.map(item=>{const expiredCount=scopedLots().filter(l=>l.itemId===item.id&&l.expiry&&expiryDays(l.expiry,state.asOf)<0).reduce((sum,l)=>sum+l.quantity,0),pendingCount=pendingExpiryLots(state,item.id,scope).reduce((sum,l)=>sum+l.quantity,0);const st=itemStatus(item),lots=availableLots(state,item.id,scope),days=lots.length?expiryDays(lots[0].expiry,state.asOf):null;return `<tr><td><div class="item-name"><div class="item-icon">${itemIcon(item)}</div><div><b>${esc(item.name)}</b><small>${esc(item.generic)}</small><small class="stock-expiry ${days!==null&&days<=90?'expiry-soon':''}">หมดอายุเร็วสุด ${lots.length?(lots[0].expiry?date(lots[0].expiry,true):'ไม่กำหนดวันหมดอายุ'):'ไม่มีล็อตพร้อมใช้'}</small></div></div></td><td><span class="muted small">${esc(item.category)}</span></td><td class="num"><b class="balance">${n(st.balance)}</b><small class="unit">${esc(item.unit)}</small>${expiredCount?`<div class="expired-note">หมดอายุ ${expiredCount} ${esc(item.unit)}</div>`:''}${pendingCount?`<div class="stock-expiry expiry-soon">รอยืนยันวันหมดอายุ ${n(pendingCount)} ${esc(item.unit)}</div>`:''}</td><td><span class="small" style="color:${days!==null&&days<=90?'var(--orange)':'#87978b'}">${lots.length?(lots[0].expiry?date(lots[0].expiry,true):'ไม่กำหนดวันหมดอายุ'):'—'}</span></td><td>${badge(st.label,st.key)}</td><td><button class="icon-button" data-action="detail:${item.id}" aria-label="ดูรายละเอียด ${esc(item.name)}">${icon('chevron')}</button></td></tr>`;}).join('')}</tbody></table>${!rows.length?`<div class="empty">${icon('search')}<h3>ไม่พบรายการที่ค้นหา</h3><p>ลองเปลี่ยนชื่อหรือเลือกตัวกรองอื่น</p></div>`:''}</div><div class="table-footer"><span>แสดง ${rows.length} รายการ · ยอดพร้อมใช้ไม่นับล็อตหมดอายุและล็อตที่รอยืนยันวันหมดอายุ</span><span>เรียงตามทะเบียนรายการ</span></div></section>`;
}
function locations(){
 const ls=scopedLocations();
 return `${header('จุดปฐมพยาบาล','ดูแลสต็อกและเลือกวิธีบันทึกการเบิกให้เหมาะกับแต่ละจุด','CARE POINTS',button('ดูเกณฑ์ความพร้อม','readiness','info')+button('เพิ่มจุด','newlocation','cross','primary'))}
 <div class="note-banner">${icon('info')} บริษัทเดียวกันมีได้ทั้งจุดที่เจ้าหน้าที่จ่ายให้ และจุดที่ผู้เบิกหยิบใช้แล้วบันทึกเอง</div>
 <div class="locations-grid">${ls.map(l=>{
  const st=locationStatus(state,l.id),count=new Set(state.thresholds.filter(t=>t.locationId===l.id).map(x=>x.itemId)).size,self=l.issueMode==='self_service';
  return `<article class="location-card"><div class="location-card-top"><div class="place-icon">${itemIcon(l)}</div>${badge(st.ready?'พร้อมใช้งาน':st.expiredLots.length?'พบของหมดอายุ':st.pendingLots.length?'รอยืนยันวันหมดอายุ':st.hasIssue?'มีปัญหาจากผลตรวจ':st.unconfigured?'ยังไม่กำหนดรายการ':st.lowItems.length?'ต้องเติมของ':'ถึงรอบตรวจ',st.ready?'ok':st.expiredLots.length?'expired':'warn')}</div>
  <h3>${esc(l.name)}</h3><p>${esc(l.area)}</p><button class="btn text" data-action="editlocation:${l.id}">แก้ไขข้อมูลจุด</button>
  <div class="point-mode"><span>${icon(self?'out':'shield')}${self?'ผู้เบิกบันทึกเอง':'เจ้าหน้าที่บันทึกให้'}</span><button class="btn text" data-action="pointmode:${l.id}" aria-label="ตั้งค่าวิธีเบิก ${esc(l.name)}">ตั้งค่า</button></div>
  <div class="location-meta"><div><small>ประเภทจุด</small><b>${esc(l.type)}</b></div><div><small>รายการประจำจุด</small><b>${count} รายการ</b></div></div>
  <div class="location-card-bottom"><small>${st.overdue?'<span style="color:var(--orange)">ถึงรอบตรวจ · </span>':''}${l.lastChecked?'ตรวจ '+date(l.lastChecked):'ยังไม่เคยตรวจ'}</small><button class="btn text" data-action="inspect:${l.id}">ตรวจจุดนี้ ${icon('arrow')}</button></div>
  ${self?`<button class="btn point-entry" data-action="take:${l.id}">${icon('out')}ลิงก์ / QR สำหรับเบิกเอง${icon('arrow')}</button>`:`<button class="btn point-entry" data-action="record:issue::${l.id}">${icon('cross')}บันทึกจ่ายให้พนักงาน${icon('arrow')}</button>`}</article>`;
 }).join('')}</div>`;
}
function historyPage(){
 const events=scopedEvents().filter(e=>historyKind==='all'||e.kind===historyKind).filter(e=>`${itemBy(e.itemId)?.name} ${e.requester?.name||''} ${e.requester?.code||''} ${e.recipientPerson?.name||e.recipient} ${e.recordedBy?.name||''} ${e.note}`.toLowerCase().includes(query.toLowerCase()));
 return `${header('ประวัติรายการ','ตรวจสอบว่าใครเบิก ใครได้รับ ใครเป็นผู้บันทึก และใช้จากล็อตใด','STOCK MOVEMENTS',button('ส่งออก','export:history','download')+button('บันทึกรายการ','record:issue','cross','primary'))}
 <div class="toolbar"><label class="search">${icon('search')}<input type="search" id="search" value="${esc(query)}" placeholder="${state.historyHasMore?'ค้นหาในรายการล่าสุด':'ค้นหาชื่อ รหัสพนักงาน หรือรายการ'}" aria-label="ค้นหาประวัติ"></label><div class="toolbar-right"><select class="select" id="historyKind" aria-label="ประเภทรายการ"><option value="all">ทุกประเภทรายการ</option>${Object.entries(kinds).map(([id,label])=>`<option value="${id}" ${historyKind===id?'selected':''}>${label}</option>`).join('')}</select></div></div>
 <section class="panel"><div class="table-scroll"><table class="inventory-table issue-history"><thead><tr><th>รายการ / วันที่</th><th>ประเภท / จุด</th><th class="num">จำนวน</th><th>ผู้เบิก → ผู้รับจริง</th><th>ผู้บันทึก</th><th>ดู</th></tr></thead><tbody>${events.map(e=>`<tr><td><b class="history-item">${esc(itemBy(e.itemId)?.name)}</b><div class="muted small">${eventDate(e,true)} · ${esc(e.documentId||e.id)}</div></td><td>${badge(kinds[e.kind],e.kind==='receive'?'ok':e.kind==='dispose'?'expired':'neutral')}<div class="muted small">${esc(locBy(e.locationId)?.name)}${e.destinationId?` → ${esc(locBy(e.destinationId)?.name)}`:''}</div></td><td class="num"><b class="balance">${e.kind==='receive'?'+':e.kind==='transfer'?'':'−'}${n(e.quantity)}</b><small class="unit">${esc(itemBy(e.itemId)?.unit)}</small></td><td>${e.requester?`<b class="history-person">${esc(e.requester.name)}</b><div class="muted small">${e.requester.code?esc(e.requester.code)+' · ':''}${esc(e.requester.department)}</div><div class="small">${e.onBehalf?`→ ${esc(e.recipientPerson.name)}`:'ใช้เอง'}</div>`:`<span class="small">${esc(e.recipient||'—')}</span><div class="muted small">ข้อมูลเดิม · ไม่ระบุผู้เบิกแยก</div>`}</td><td><span class="small">${esc(e.recordedBy?.name||'ไม่ได้บันทึก')}</span><div>${e.recordingMode?badge(e.recordingMode==='legacy'?'นำเข้าจาก Excel':e.recordingMode==='self_service'?'บันทึกเอง':'เจ้าหน้าที่บันทึก',e.recordingMode==='self_service'?'neutral':'ok'):''}</div></td><td><button class="icon-button" data-action="event:${e.id}" aria-label="รายละเอียดรายการ ${esc(e.id)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table>${!events.length?`<div class="empty">${icon('clock')}<h3>ยังไม่มีรายการในมุมมองนี้</h3><p>เปลี่ยนตัวกรอง หรือเริ่มบันทึกรายการใหม่</p></div>`:''}</div><div class="table-footer"><span>${events.length} บรรทัดรายการ${state.historyHasMore?'ล่าสุด (ยังมีรายการก่อนหน้านี้)':''} · เอกสารเดียวกันคือเบิกพร้อมกัน</span><span>ข้อมูลของบริษัทที่เลือก</span></div></section>`;
}
function reports(){const events=scopedEvents().filter(e=>e.kind==='issue'),s=stats(state,scope);let days=Array.from({length:7},(_,i)=>{const d=new Date(`${state.asOf}T12:00:00`);d.setDate(d.getDate()-6+i);const iso=d.toISOString().slice(0,10);return {date:iso,count:state.usageSummary?.dailyUsesByLocation?.filter(r=>r.date===iso&&(scope==='all'||r.locationId===scope)).reduce((sum,r)=>sum+Number(r.count),0)??0};});const max=Math.max(1,...days.map(d=>d.count));return `${header('รายงานและข้อมูลเชิงลึก','เห็นการใช้จริง วางแผนเติมสต็อก และตรวจสอบย้อนหลัง','REPORTS',button('พิมพ์รายงาน','print','print'))}<div class="intro-grid"><div class="panel" style="padding:23px 25px"><span class="muted small">การจ่ายใช้เดือน${monthLabel()}</span><div style="font:550 40px/1.6 system-ui">${s.monthUses}<span style="font:12px var(--font);color:var(--muted);margin-left:10px">รายการ</span></div><span class="muted small">นับรายการจ่ายใช้ ไม่รวมการโอนระหว่างจุด</span></div><div class="panel" style="padding:23px 25px"><span class="muted small">ความพร้อมในพื้นที่ที่เลือก</span><div style="font:550 40px/1.6 system-ui">${Math.round((s.locationCount?s.readyLocations/s.locationCount*100:0))}<span style="font-size:20px;color:var(--muted)">%</span></div><span class="muted small">${s.locationCount?`${s.readyLocations} จาก ${s.locationCount} จุด ผ่านเกณฑ์ความพร้อม`:'ยังไม่มีจุดจัดเก็บ'}</span></div></div><div class="report-layout"><section class="panel"><div class="panel-header"><div><h2>การจ่ายใช้ใน 7 วันล่าสุด</h2><p class="panel-subtitle">จำนวนรายการ ไม่รวมหน่วยสินค้าต่างชนิดเข้าด้วยกัน</p></div></div><div class="usage-chart" role="img" aria-label="${days.map(d=>`${date(d.date)} ${d.count} รายการ`).join(', ')}">${days.map(d=>`<div class="chart-col"><div class="bar" style="--height:${Math.max(3,d.count/max*140)}px"><b>${d.count||'—'}</b></div><small>${date(d.date)}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-header"><h2>ส่งออกรายงาน</h2></div><div class="report-options"><button class="report-option" data-action="export:stock">${icon('box')}<span><b>ยอดคงเหลือแยกจุด</b><p>พร้อมใช้ / หมดอายุ / เกณฑ์ขั้นต่ำ · CSV</p></span>${icon('download')}</button><button class="report-option" data-action="export:history">${icon('clock')}<span><b>ประวัติการทำรายการ</b><p>รับเข้า จ่ายใช้ โอนย้าย และตัดจำหน่าย${state.historyHasMore?' · ล่าสุด 500 บรรทัด':''} · CSV</p></span>${icon('download')}</button><button class="report-option" data-action="export:inspection">${icon('checkCircle')}<span><b>ประวัติตรวจความพร้อม</b><p>วันที่ตรวจ สถานะ และหมายเหตุ · CSV</p></span>${icon('download')}</button></div></section></div>`;}
function settings(){return `${header('เหมาะกับวิธีทำงานของคุณ','ตั้งค่าตามวิธีดูแลพื้นที่ของแต่ละบริษัท','WORKSPACE SETTINGS','')}<section class="panel settings-card"><div class="setting-row"><div><b>ชื่อบริษัท</b><p>${esc(state.company.name)}</p></div>${badge('ข้อมูลบริษัท','neutral')}</div>${state.permissions?.canClinical?`<div class="setting-row"><div><b>บริการห้องพยาบาล</b><p>เปิดบันทึกการดูแล เวลาเข้า–ออก อาการ และการส่งต่อ แยกจากสต็อกทั่วไป</p></div><input id="infirmaryMode" class="switch" type="checkbox" role="switch" aria-label="เปิดใช้บริการห้องพยาบาล" ${state.company.infirmary?'checked':''} ${staleData?'disabled':''}></div>`:''}<div class="setting-row"><div><b>วิธีบันทึกการเบิกประจำจุด</b><p>เลือกเจ้าหน้าที่บันทึกให้ หรือเปิดหน้าผู้เบิกจากลิงก์ / QR ประจำจุด</p></div>${button('ตั้งค่าจุด','nav:locations','pin')}</div><div class="setting-row"><div><b>ทะเบียนยาและเวชภัณฑ์</b><p>กำหนดชื่อ หมวด หน่วย และการติดตามวันหมดอายุ</p></div>${button('เพิ่มรายการ','newitem','cross')}</div><div class="setting-row"><div><b>เกณฑ์ขั้นต่ำประจำจุด</b><p>กำหนดตามความเหมาะสมของพื้นที่ เพื่อให้คำเตือนตรงกับของที่ต้องเตรียมจริง</p></div>${button('จัดการเกณฑ์','thresholds','settings')}</div><div class="setting-row"><div><b>ข้อมูลล่าสุด</b><p>รายการบันทึกและยอดคงเหลืออยู่บนระบบกลาง</p></div>${button('โหลดใหม่','refresh','refresh')}</div></section>`;}
function infirmary(){const visits=state.visits||[];return `${header('บริการห้องพยาบาล','บันทึกการช่วยเหลือ และติดตามการให้บริการในพื้นที่','INFIRMARY SERVICES',button('บันทึกบริการ','newvisit','cross','primary'))}<section class="panel">${!visits.length?`<div class="empty">${icon('heart')}<h3>พร้อมบันทึกบริการครั้งแรก</h3><p>ส่วนเสริมสำหรับบริษัทที่มีห้องพยาบาล<br>บันทึกการให้บริการจริงตามสิทธิ์ที่ได้รับ</p>${button('บันทึกบริการ','newvisit','cross','primary')}</div>`:`<div class="table-scroll"><table class="inventory-table"><thead><tr><th>วันที่</th><th>ผู้ใช้บริการ</th><th>ประเภทบริการ</th><th>อาการ / บันทึก</th></tr></thead><tbody>${visits.map(v=>`<tr><td>${date(v.date,true)}${v.timeIn?`<div class="muted small">${esc(v.timeIn)}${v.timeOut?` – ${esc(v.timeOut)}`:''}</div>`:''}</td><td>${esc(v.person)}</td><td>${badge(v.service,'neutral')}</td><td>${esc(v.note)}</td></tr>`).join('')}</tbody></table></div>`}</section>`;}
function bind(){
 document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=e=>{e.preventDefault();navigate(el.dataset.nav);});
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=e=>{e.preventDefault();action(el.dataset.action);});
 document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;render();});
 $('#scope').onchange=e=>{scope=e.target.value;render();};
 const search=$('#search');if(search)search.oninput=e=>{query=e.target.value;const start=e.target.selectionStart;render();$('#search').focus();try{$('#search').setSelectionRange(start,start);}catch{}};
 if($('#category'))$('#category').onchange=e=>{filter=e.target.value;render();};
 if($('#historyKind'))$('#historyKind').onchange=e=>{historyKind=e.target.value;render();};
 if($('#infirmaryMode'))$('#infirmaryMode').onchange=async e=>{const enabled=e.target.checked;e.target.disabled=true;try{await saveAction({action:'settings',infirmary:enabled});render();toast(enabled?'เปิดเมนูบริการห้องพยาบาลแล้ว':'ปิดส่วนเสริมห้องพยาบาลแล้ว');}catch(error){e.target.checked=!enabled;e.target.disabled=false;toast(error.message);}};
}
function action(code){const [type,a,b,c,d]=code.split(':');if(staleData&&['record','newlocation','newitem','editlocation','edititem','pointmode','take','inspect','thresholds','newvisit'].includes(type)){toast('กรุณาโหลดข้อมูลล่าสุดก่อนทำรายการต่อ');return;}if(type==='nav')navigate(a);if(type==='take')openPointLink(a);if(type==='pointmode')openPointMode(a);if(type==='event')openEvent(a);if(type==='record')openTransaction(a,b||undefined,c||undefined,d||undefined);if(type==='detail')openDetail(a);if(type==='inspect')openInspection(a);if(type==='location'){scope=a;navigate('inventory');}if(type==='expiry'){filter='expiry';page='inventory';location.hash=page;render();}if(type==='search'){navigate('inventory');$('#search')?.focus();}if(type==='alerts'){navigate('overview');$('.attention-list')?.scrollIntoView({block:'center',behavior:'smooth'});}if(type==='export')exportCsv(a);if(type==='print')window.print();if(type==='thresholds')openThresholds(a);if(type==='newvisit')openVisit();if(type==='newlocation')openLocation();if(type==='newitem')openItem();if(type==='edititem')openItem(a);if(type==='editlocation')openLocation(a);if(type==='refresh')refresh().then(render).catch(e=>toast(e.message));if(type==='guide')openGuide();if(type==='more')openMore();if(type==='readiness')openReadiness();}
let returnFocus=null;
$('#drawer').addEventListener('cancel',e=>{if($('#drawer').dataset.pending==='true'){e.preventDefault();toast('ยังยืนยันผลไม่ได้ กรุณาลองส่งคำขอเดิมอีกครั้ง');}});
function pendingForm(uncertain){window.parent.postMessage({type:'first-aid-pending',pending:uncertain},location.origin);const dialog=$('#drawer');if(uncertain)dialog.dataset.pending='true';else delete dialog.dataset.pending;dialog.querySelectorAll('input,select,textarea,button:not([type="submit"])').forEach(el=>el.disabled=uncertain);}
function showDrawer(title,body,footer='',eyebrow='FIRST AID WORKSPACE'){
 const dialog=$('#drawer');if(!dialog.open)returnFocus=document.activeElement;
 dialog.innerHTML=`<header class="drawer-header"><div><div class="eyebrow">${eyebrow}</div><h2 id="drawer-title">${title}</h2></div><button class="icon-button" data-close aria-label="ปิดแผง">${icon('close')}</button></header><div class="drawer-body">${body}</div>${footer?`<footer class="drawer-footer">${footer}</footer>`:''}`;
 delete dialog.dataset.pending;dialog.querySelectorAll('[data-close]').forEach(el=>el.onclick=()=>{if(dialog.dataset.pending==='true')return toast('ยังยืนยันผลไม่ได้ กรุณาลองส่งคำขอเดิมอีกครั้ง');dialog.close();});
 if(!dialog.open)dialog.showModal();
 dialog.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{const code=el.dataset.action;dialog.close();action(code);});
}
$('#drawer').addEventListener('close',()=>{window.parent.postMessage({type:'first-aid-pending',pending:false},location.origin);if(returnFocus?.isConnected)returnFocus.focus();});
$('#drawer').addEventListener('click',e=>{if(e.target===$('#drawer')&&e.clientX<$('#drawer').getBoundingClientRect().left&&$('#drawer').dataset.pending!=='true')$('#drawer').close();});
function optionsLocations(selected){return state.locations.map(l=>`<option value="${esc(l.id)}" ${l.id===selected?'selected':''}>${esc(l.name)}</option>`).join('');}
function optionsItems(selected){return state.items.map(i=>`<option value="${esc(i.id)}" ${i.id===selected?'selected':''}>${esc(i.name)} · ${esc(i.unit)}</option>`).join('');}
function employeeOptions(selected=''){
 return `<option value="">เลือกชื่อหรือรหัสพนักงาน</option><option value="manual">บุคคลอื่น / ไม่มีรหัสพนักงาน</option>${state.employees.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.code)} · ${esc(p.name)} · ${esc(p.department)}</option>`).join('')}`;
}
function openTransaction(kind='issue',itemId,locationId=scope==='all'?state.locations[0]?.id:scope,destinationId){
 if(!state.locations.length)return openLocation();if(!state.items.length)return openItem();
 destinationId=destinationId||state.locations.find(l=>l.id!==locationId)?.id||locationId;
 const receive=kind==='receive',transfer=kind==='transfer',dispose=kind==='dispose',issue=kind==='issue';
 const activeItem=itemBy(itemId)||state.items[0];itemId=activeItem.id;
 let rows=[{itemId,quantity:1,lotId:''}],busy=false;const idempotencyKey=crypto.randomUUID();
 const body=`<div class="segmented" role="tablist" aria-label="ประเภทรายการ">${Object.entries(kinds).map(([id,label])=>`<button role="tab" aria-selected="${id===kind}" class="${id===kind?'active':''}" data-kind="${id}">${label}</button>`).join('')}</div>
 <form id="transaction-form"><div id="form-error" class="form-error" role="alert" tabindex="-1"></div>
 <div class="field"><label for="tx-location">${transfer?'จุดต้นทาง':'จุดปฐมพยาบาล'}</label><select id="tx-location">${optionsLocations(locationId)}</select><div id="tx-mode-note" class="field-context"></div></div>
 ${transfer?`<div class="field"><label for="tx-destination">จุดปลายทาง</label><select id="tx-destination">${optionsLocations(destinationId===locationId?(state.locations.find(l=>l.id!==locationId)?.id||locationId):destinationId)}</select></div>`:''}
 ${issue?`<section class="identity-section"><div class="section-kicker">${icon('shield')}ผู้เกี่ยวข้องกับการเบิก</div><div class="field"><label for="tx-requester">ผู้เบิก / ผู้หยิบ <span class="required-text">จำเป็น</span></label><select id="tx-requester" required>${employeeOptions()}</select><small class="hint" id="tx-requester-info">เลือกพนักงานเพื่อบันทึกชื่อ รหัส และแผนก</small></div><div id="tx-requester-manual" hidden><div class="field"><label for="tx-requester-name">ชื่อ-นามสกุลผู้เบิก <span class="required-text">จำเป็น</span></label><input id="tx-requester-name" maxlength="100" placeholder="ชื่อ-นามสกุล"></div><div class="field"><label for="tx-requester-dept">หน่วยงาน / บริษัทผู้เบิก <span class="required-text">จำเป็น</span></label><input id="tx-requester-dept" maxlength="100"></div></div><label class="on-behalf"><input id="tx-onbehalf" type="checkbox">เบิกให้ผู้อื่น</label><div class="field" id="tx-recipient-field" hidden><label for="tx-recipient">ผู้รับจริง <span class="required-text">จำเป็นเมื่อเบิกแทน</span></label><select id="tx-recipient">${employeeOptions()}</select><div id="tx-recipient-manual" hidden><div class="field" style="margin-top:12px"><label for="tx-recipient-name">ชื่อ-นามสกุลผู้รับจริง</label><input id="tx-recipient-name" maxlength="100"></div><div class="field"><label for="tx-recipient-dept">หน่วยงาน / บริษัทผู้รับจริง</label><input id="tx-recipient-dept" maxlength="100"></div></div></div><div class="recorder-note">${icon('checkCircle')}<span>ผู้จ่าย / ผู้บันทึก: <b>${esc(state.session.name)}</b><small>บัญชีที่เข้าสู่ระบบ · เจ้าหน้าที่บันทึกให้</small></span></div></section>`:''}
 <div id="tx-rows"></div>${issue?`<button class="btn text" type="button" id="add-item">${icon('cross')}เพิ่มรายการที่ใช้ร่วมกัน</button>`:''}
 ${receive?`<div class="field-grid"><div class="field"><label for="tx-lot">เลขล็อต <small>(ถ้ามี)</small></label><input id="tx-lot" maxlength="60" placeholder="เลขล็อตตามบรรจุภัณฑ์"></div><div class="field"><label for="tx-expiry">วันหมดอายุ</label><input id="tx-expiry" type="date" min="${state.asOf}" required></div></div>`:''}
 <div class="field-grid" style="margin-top:15px"><div class="field"><label for="tx-date">วันที่ทำรายการ</label><input id="tx-date" type="date" value="${state.asOf}" max="${state.asOf}" required></div>${!issue?`<div class="field"><label for="tx-person">ผู้ดำเนินการ <small>(ถ้ามี)</small></label><input id="tx-person" value="${esc(state.session.name)}" maxlength="100"></div>`:''}</div>
 <div class="field"><label for="tx-note">${dispose?'เหตุผลที่ตัดจำหน่าย':'วัตถุประสงค์ / หมายเหตุ'} <small>${dispose?'':'(ถ้ามี)'}</small></label><textarea id="tx-note" placeholder="${dispose?'เช่น หมดอายุ / บรรจุภัณฑ์ชำรุด':'บันทึกเพิ่มเติมเมื่อจำเป็น'}" ${dispose?'required':''} maxlength="500"></textarea></div>
 <p class="form-note">${receive?'แยกแต่ละล็อตตามวันหมดอายุ เพื่อให้ติดตามและเลือกล็อตได้ถูกต้อง':dispose?'บันทึกการตัดจำหน่ายพร้อมเหตุผล แยกจากการจ่ายใช้':'เลือกล็อตให้ตรงกับของที่จ่ายจริง ระบบเสนอวันหมดอายุเร็วสุดให้ และไม่นำล็อตหมดอายุมาจ่ายใช้'}<br>ชื่อผู้เบิกระบุตามรายการ ส่วนผู้บันทึกเก็บจากบัญชีที่เข้าสู่ระบบ</p></form>`;
 showDrawer(issue?'บันทึกจ่ายให้พนักงาน':`${kinds[kind]}ยาและเวชภัณฑ์`,body,`<button class="btn" data-close>ยกเลิก</button><button type="submit" form="transaction-form" id="tx-submit" class="btn primary">${icon('check')}ยืนยัน${kinds[kind]}</button>`,'NEW STOCK MOVEMENT');
 const modeNote=()=>{
  const l=locBy(locationId);
  $('#tx-mode-note').innerHTML=issue?(l.issueMode==='self_service'?`${icon('info')}จุดนี้ให้บันทึกเองได้ · คุณกำลังบันทึกในฐานะเจ้าหน้าที่ <button type="button" class="btn text" id="tx-go-self">เปิดหน้าผู้เบิก ${icon('arrow')}</button>`:`${icon('shield')}จุดนี้ให้เจ้าหน้าที่เป็นผู้บันทึก`):'';
  if($('#tx-go-self'))$('#tx-go-self').onclick=()=>{$('#drawer').close();openPointLink(locationId);};
 };
 const drawRows=()=>{
  $('#tx-rows').innerHTML=rows.map((r,index)=>{
   const item=itemBy(r.itemId),balance=dispose?state.lots.filter(l=>l.itemId===r.itemId&&l.locationId===locationId).reduce((a,l)=>a+l.quantity,0):itemBalance(state,r.itemId,locationId),lots=availableLots(state,r.itemId,locationId);
   if(r.lotId&&!lots.some(l=>l.id===r.lotId))r.lotId='';
   const first=lots[0];
   return `<section class="tx-line"><div class="field"><label for="tx-item-${index}">รายการ${rows.length>1?`ที่ ${index+1}`:''}${index?` <button type="button" class="btn text" data-remove="${index}" style="float:right;color:var(--red)">นำออก</button>`:''}</label><select class="tx-item" data-index="${index}" id="tx-item-${index}">${optionsItems(r.itemId)}</select></div>
   ${!receive?`<div class="available-box"><div><p>${dispose?'คงเหลือทั้งหมด':'จำนวนพร้อมใช้'} ณ จุดนี้</p><span>${dispose?'รวมล็อตหมดอายุ':first?`หมดอายุเร็วสุด ${(first.expiry?date(first.expiry,true):'ไม่กำหนดวันหมดอายุ')}`:'ยังไม่มีล็อตพร้อมใช้'}</span></div><b>${n(balance)}<small>${esc(item.unit)}</small></b></div>`:''}
   ${issue?`<div class="field"><label for="tx-lot-${index}">ล็อตที่จ่ายจริง</label><select class="tx-actual-lot" data-index="${index}" id="tx-lot-${index}">${lots.length>1?`<option value="" ${!r.lotId?'selected':''}>เลือกตาม FEFO อัตโนมัติ</option>`:''}${lots.map(l=>`<option value="${esc(l.id)}" ${r.lotId===l.id?'selected':''}>${esc(l.code)} · หมดอายุ ${l.expiry?date(l.expiry,true):'ไม่กำหนดวันหมดอายุ'} · ${l.quantity} ${esc(item.unit)}</option>`).join('')||'<option value="">ไม่มีล็อตพร้อมใช้</option>'}</select><small class="hint">ตรวจวันหมดอายุบนบรรจุภัณฑ์ให้ตรงกับล็อตนี้</small></div>`:''}
   <div class="field"><label for="tx-qty-${index}">จำนวน <small>(${esc(item.unit)})</small></label><input class="tx-qty" data-index="${index}" id="tx-qty-${index}" type="number" min="1" step="1" value="${r.quantity}" required></div></section>`;
  }).join('');
  document.querySelectorAll('.tx-item').forEach(el=>el.onchange=e=>{rows[+el.dataset.index].itemId=e.target.value;rows[+el.dataset.index].lotId='';drawRows();if(receive){const required=itemBy(rows[0].itemId)?.trackExpiry!==false;$('#tx-expiry').required=required;$('#tx-expiry').closest('.field').querySelector('label').textContent=required?'วันหมดอายุ':'วันหมดอายุ (ถ้ามี)';}});
  document.querySelectorAll('.tx-qty').forEach(el=>el.oninput=e=>rows[+el.dataset.index].quantity=Number(e.target.value));
  document.querySelectorAll('.tx-actual-lot').forEach(el=>{rows[+el.dataset.index].lotId=el.value;el.onchange=()=>rows[+el.dataset.index].lotId=el.value;});
  document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{rows.splice(+el.dataset.remove,1);drawRows();});
 };
 drawRows();modeNote();
 const updateExpiryRequirement=()=>{if(receive){const required=itemBy(rows[0].itemId)?.trackExpiry!==false;$('#tx-expiry').required=required;$('#tx-expiry').closest('.field').querySelector('label').textContent=required?'วันหมดอายุ':'วันหมดอายุ (ถ้ามี)';}};updateExpiryRequirement();
 const previousItemChange=$('#tx-item-0')?.onchange;if(receive&&previousItemChange)$('#tx-item-0').onchange=e=>{previousItemChange(e);updateExpiryRequirement();};
 $('#tx-location').onchange=e=>{locationId=e.target.value;rows.forEach(r=>r.lotId='');drawRows();modeNote();};
 document.querySelectorAll('[data-kind]').forEach(el=>el.onclick=()=>openTransaction(el.dataset.kind,rows[0].itemId,locationId,destinationId));
 if(issue){
  const manualFields=(who,show)=>{$(`#tx-${who}-manual`).hidden=!show;$(`#tx-${who}-name`).required=show;$(`#tx-${who}-dept`).required=show;};
  $('#tx-onbehalf').onchange=e=>{$('#tx-recipient-field').hidden=!e.target.checked;$('#tx-recipient').required=e.target.checked;if(!e.target.checked)$('#tx-recipient').value='';manualFields('recipient',e.target.checked&&$('#tx-recipient').value==='manual');};
  $('#tx-recipient').onchange=e=>manualFields('recipient',e.target.value==='manual'&&$('#tx-onbehalf').checked);
  $('#tx-requester').onchange=e=>{const person=state.employees.find(p=>p.id===e.target.value);$('#tx-requester-info').textContent=person?`${person.code} · ${person.department} · ชื่อตามที่ระบุ`:'กรอกชื่อและหน่วยงานตามที่ผู้เบิกระบุ';manualFields('requester',e.target.value==='manual');const previous=$('#tx-recipient').value;$('#tx-recipient').innerHTML=employeeOptions(previous);if(e.target.value!=='manual'&&e.target.value){const duplicate=$(`#tx-recipient option[value="${e.target.value}"]`);if(duplicate)duplicate.remove();}if(previous===e.target.value&&previous!=='manual')$('#tx-recipient').value='';manualFields('recipient',$('#tx-onbehalf').checked&&$('#tx-recipient').value==='manual');};
  $('#add-item').onclick=()=>{if(rows.length>=8)return toast('เพิ่มได้สูงสุด 8 รายการต่อครั้ง');rows.push({itemId:state.items.find(i=>!rows.some(r=>r.itemId===i.id))?.id||state.items[0].id,quantity:1,lotId:''});drawRows();};
 }
 $('#transaction-form').onsubmit=async e=>{
  e.preventDefault();if(busy)return;busy=true;$('#tx-submit').disabled=true;
  try{
   const payload={kind,locationId,destinationId:$('#tx-destination')?.value,date:$('#tx-date').value,expiry:$('#tx-expiry')?.value,lotCode:$('#tx-lot')?.value,lines:rows,note:$('#tx-note').value};
   if(issue)Object.assign(payload,{requesterId:$('#tx-requester').value,recipientId:$('#tx-recipient').value,requesterPerson:{name:$('#tx-requester-name').value,department:$('#tx-requester-dept').value},recipientPerson:{name:$('#tx-recipient-name').value,department:$('#tx-recipient-dept').value},onBehalf:$('#tx-onbehalf').checked});
   await saveTransaction(payload,idempotencyKey);
   $('#drawer').close();render();toast(`บันทึก${kinds[kind]}สำเร็จ ${rows.length} รายการ · อัปเดตยอดแล้ว`);
  }catch(error){pendingForm(error.uncertain===true);$('#form-error').textContent=error.uncertain?'ยังยืนยันผลไม่ได้ ลองส่งคำขอเดิมอีกครั้ง โดยไม่เปลี่ยนรายการ':error.message;$('#form-error').focus();busy=false;$('#tx-submit').disabled=false;$('#tx-submit').textContent=error.uncertain?'ลองยืนยันคำขอเดิมอีกครั้ง':'ยืนยัน'+kinds[kind];}
 };
}
function openPointMode(id){
 const l=locBy(id),self=l.issueMode==='self_service';
 showDrawer('วิธีบันทึกการเบิก',`<div class="point-settings-title">${itemIcon(l)}<div><h3>${esc(l.name)}</h3><p>${esc(l.type)} · ${esc(l.area)}</p></div></div><form id="point-mode-form"><label class="mode-choice"><input type="radio" name="point-mode" value="controlled" ${!self?'checked':''}><span><b>เจ้าหน้าที่บันทึกให้</b><small>เจ้าหน้าที่เลือกผู้เบิก ผู้รับจริง และยืนยันการจ่าย · หน้าหยิบเองปิดใช้งาน</small></span>${icon('shield')}</label><label class="mode-choice"><input type="radio" name="point-mode" value="self_service" ${self?'checked':''}><span><b>ผู้เบิกบันทึกเอง</b><small>ผู้หยิบระบุตัวเอง เลือกของและจำนวน แล้วบันทึกทันที เหมาะกับตู้หรือกระเป๋าที่เปิดให้หยิบใช้</small></span>${icon('out')}</label><p class="form-note">การตั้งค่านี้ใช้เฉพาะจุดนี้ และแยกจากการเปิดใช้บริการห้องพยาบาล</p></form>`,`<button class="btn" data-close>ยกเลิก</button><button type="submit" form="point-mode-form" class="btn primary">บันทึกวิธีเบิก</button>`,'CARE POINT WORKFLOW');
 $('#point-mode-form').onsubmit=async e=>{e.preventDefault();const value=$('input[name="point-mode"]:checked').value;try{await saveAction({action:'location',id,name:l.name,type:l.type,area:l.area,issueMode:value});$('#drawer').close();render();toast('ตั้งค่าวิธีบันทึกการเบิกแล้ว');}catch(error){toast(error.message);}};
}
function openEvent(id){
 const e=state.events.find(x=>x.id===id);if(!e)return;
 const person=p=>p?`<b>${esc(p.name)}</b><small>${p.code?esc(p.code)+' · ':''}${esc(p.department||'')}</small>`:'<span class="muted">ไม่ได้ระบุในข้อมูลเดิม</span>';
 showDrawer('รายละเอียดรายการ',`<div class="event-summary"><span class="eyebrow">${esc(e.documentId||e.id)}</span><h3>${kinds[e.kind]} ${esc(itemBy(e.itemId).name)}</h3><p>${eventDate(e,true)} · ${esc(locBy(e.locationId).name)}</p><b class="event-amount">${n(e.quantity)} <small>${esc(itemBy(e.itemId).unit)}</small></b></div><dl class="event-people"><div><dt>ผู้เบิก / ผู้หยิบ</dt><dd>${person(e.requester)}</dd></div><div><dt>ผู้รับจริง</dt><dd>${person(e.recipientPerson)}${e.onBehalf?badge('เบิกแทน','neutral'):e.requester?badge('ใช้เอง','ok'):''}</dd></div><div><dt>ผู้จ่าย / ผู้บันทึก</dt><dd>${e.recordedBy?`<b>${esc(e.recordedBy.name)}</b><small>${e.recordingMode==='legacy'?'นำเข้าจาก Excel · ไม่ใช่การยืนยันผู้บันทึกเดิม':e.recordingMode==='self_service'?'ผู้เบิกบันทึกเอง · ระบุด้วยตนเอง':'เจ้าหน้าที่บันทึกให้ · บัญชีที่เข้าสู่ระบบ'}</small>`:'<span class="muted">ไม่ได้ระบุในข้อมูลเดิม</span>'}</dd></div></dl><h3 class="detail-section">ล็อตที่บันทึกตัดออก</h3>${e.allocations?.length?e.allocations.map(l=>`<div class="lot-row"><div><b>${esc(l.code)}</b><p>หมดอายุ ${l.expiry?date(l.expiry,true):'ไม่กำหนดวันหมดอายุ'}</p></div><b>${l.quantity} ${esc(itemBy(e.itemId).unit)}</b></div>`).join(''):'<p class="form-note">ข้อมูลเดิมไม่ได้เก็บรายละเอียดล็อตที่ตัดออก</p>'}${e.note?`<div class="detail-section"><h3>หมายเหตุ</h3><p class="muted small">${esc(e.note)}</p></div>`:''}${e.requester?'<p class="form-note" style="margin-top:24px">ชื่อผู้เบิกและผู้รับเป็นข้อมูลที่ระบุในการเบิก ไม่ใช่การยืนยันตัวตน</p>':''}`,`<button class="btn primary" data-close>ปิดรายละเอียด</button>`,'ISSUE TRACEABILITY');
}
function openDetail(id){
 const item=itemBy(id),lots=scopedLots().filter(l=>l.itemId===id).sort((a,b)=>(a.expiry||'9999-12-31').localeCompare(b.expiry||'9999-12-31')),usable=itemBalance(state,id,scope),expired=lots.filter(l=>l.expiry&&expiryDays(l.expiry,state.asOf)<0),pending=pendingExpiryLots(state,id,scope);
 showDrawer('รายละเอียดรายการ',`<div class="item-hero"><div class="item-icon">${itemIcon(item)}</div><div><h3>${esc(item.name)}</h3><p>${esc(item.generic)} · ${esc(item.category)}</p></div></div><div class="detail-balance"><p>ยอดพร้อมใช้${scope==='all'?'ทุกจุด':` · ${esc(locBy(scope).name)}`}</p><b>${n(usable)}</b><span>${esc(item.unit)}</span>${expired.length?`<p style="color:var(--red)">แยกจากล็อตหมดอายุ ${expired.reduce((s,l)=>s+l.quantity,0)} ${esc(item.unit)} · รอตัดจำหน่าย</p>`:''}${pending.length?`<p style="color:var(--orange)">รอยืนยันวันหมดอายุ ${n(pending.reduce((sum,l)=>sum+l.quantity,0))} ${esc(item.unit)} · แยกจากยอดพร้อมใช้</p><p class="form-note">ตรวจวันหมดอายุและจำนวนแยกตามล็อตบนบรรจุภัณฑ์ แล้วติดต่อผู้ดูแลเพื่อยืนยันข้อมูลเดิม</p>`:''}</div><h3>ล็อตและจุดจัดเก็บ</h3>${lots.map(l=>{const d=l.expiry?expiryDays(l.expiry,state.asOf):Infinity,held=item.trackExpiry!==false&&!l.expiry;return `<div class="lot-row"><div><b style="font-weight:500">${esc(locBy(l.locationId).name)}</b><p>${esc(l.code)} · ${held?'รอยืนยันวันหมดอายุ':`หมดอายุ ${l.expiry?date(l.expiry,true):'ไม่กำหนดวันหมดอายุ'}`}</p>${held?badge('รอยืนยัน · แยกออกจากยอดพร้อมใช้','warn'):d<0?badge('หมดอายุ · แยกออกจากยอดพร้อมใช้','expired'):d<=90?badge(`เหลือ ${d} วัน`,'warn'):''}</div><div style="text-align:right"><b>${n(l.quantity)} ${esc(item.unit)}</b><br>${held?'':`<button class="btn text" data-action="record:${d<0?'dispose':'issue'}:${item.id}:${l.locationId}">${d<0?'ตัดจำหน่าย':'จ่ายจากจุดนี้'} ${icon('arrow')}</button>`}</div></div>`;}).join('')||'<p class="muted">ยังไม่มีล็อตในพื้นที่ที่เลือก</p>'}`,`<button class="btn" data-action="edititem:${id}">แก้ไขทะเบียน</button><button class="btn" data-close>ปิด</button><button class="btn primary" data-action="record:receive:${id}">${icon('in')}รับเข้าเพิ่ม</button>`,'ITEM & LOT DETAILS');
}
function openInspection(id){const createId=crypto.randomUUID();const l=locBy(id),status=locationStatus(state,id);const ids=[...new Set(state.thresholds.filter(t=>t.locationId===id).map(t=>t.itemId))];showDrawer(`ตรวจ${esc(l.name)}`,`<p class="muted small" style="margin-bottom:20px">${esc(l.type)} · ${esc(l.area)}<br>ยืนยันจำนวนตามที่พบจริง และตรวจสภาพก่อนบันทึก</p><form id="inspection-form"><div class="form-error" role="alert" tabindex="-1"></div><div class="note-banner">${icon('info')} ตรวจแล้วอาจยังต้องเติมของหรือตัดของหมดอายุ ระบบจะเก็บสิ่งที่ต้องจัดการไว้</div>${ids.map(itemId=>{const i=itemBy(itemId),st=getItemStatus(state,i,id);return `<label class="check-row"><input type="checkbox" required><span><b>${esc(i.name)}</b><small>พร้อมใช้ ${st.balance} ${esc(i.unit)} · ขั้นต่ำ ${state.thresholds.find(t=>t.itemId===itemId&&t.locationId===id)?.min}</small></span>${badge(st.label,st.key)}</label>`;}).join('')}${status.expiredLots.length?`<div class="form-error" style="margin-top:18px">พบของหมดอายุ ${status.expiredLots.length} ล็อต การตรวจครั้งนี้ยังไม่ทำให้จุดพร้อมใช้</div>`:''}<div class="field" style="margin-top:22px"><label for="inspect-note">สิ่งที่พบ / หมายเหตุ</label><textarea id="inspect-note" maxlength="500" placeholder="สภาพบรรจุภัณฑ์ รายการที่ต้องเติม หรือยอดที่ต้องตรวจสอบ"></textarea></div><label class="check-row"><input type="checkbox" required><span>ตรวจสภาพตู้ ความสะอาด และการเข้าถึงแล้ว</span></label><label class="check-row"><input type="checkbox" id="inspect-issue"><span><b>พบปัญหาที่ต้องแก้ไข</b><small>เช่น ยอดจริงไม่ตรง ของชำรุด หรือเข้าถึงตู้ไม่ได้ · จุดนี้จะยังไม่พร้อมใช้</small></span></label></form>`,`<button class="btn" data-close>ยกเลิก</button><button type="submit" form="inspection-form" class="btn primary">${icon('checkCircle')}บันทึกผลตรวจ</button>`,'CARE POINT INSPECTION');formSave('inspection-form',()=>saveAction({action:'inspection',createId,locationId:id,notes:$('#inspect-note').value,hasIssue:$('#inspect-issue').checked}),'บันทึกผลตรวจแล้ว');}
function openThresholds(locationId){const l=locationId||(scope==='all'?state.locations[0]?.id:scope);if(!l)return openLocation();const show=selected=>{showDrawer('เกณฑ์ขั้นต่ำประจำจุด',`<div class="field"><label for="threshold-location">จุดปฐมพยาบาล</label><select id="threshold-location">${optionsLocations(selected)}</select></div><form id="threshold-form">${state.items.map(i=>({itemId:i.id,min:state.thresholds.find(t=>t.locationId===selected&&t.itemId===i.id)?.min||0})).map(t=>`<div class="field-grid" style="align-items:center"><label for="min-${t.itemId}">${esc(itemBy(t.itemId).name)} <small class="muted">(${esc(itemBy(t.itemId).unit)})</small></label><div class="field" style="margin-bottom:12px"><input id="min-${t.itemId}" type="number" min="0" step="1" value="${t.min}" required></div></div>`).join('')}<p class="form-note">กำหนดจำนวนขั้นต่ำตามความเหมาะสมของแต่ละพื้นที่ คำเตือนและความพร้อมจะคำนวณใหม่จากเกณฑ์นี้</p></form>`,`<button class="btn" data-close>ยกเลิก</button><button type="submit" form="threshold-form" class="btn primary">บันทึกเกณฑ์</button>`,'LOCATION THRESHOLDS');$('#threshold-location').onchange=e=>show(e.target.value);$('#threshold-form').onsubmit=async e=>{e.preventDefault();try{await saveAction({action:'thresholds',locationId:selected,thresholds:state.items.map(i=>({itemId:i.id,min:Number($(`#min-${i.id}`).value)}))});$('#drawer').close();render();toast('บันทึกเกณฑ์ขั้นต่ำแล้ว');}catch(error){toast(error.message);}};};show(l);}
function openVisit(){const createId=crypto.randomUUID();if(!state.permissions?.canClinical)return toast('บัญชีนี้ไม่มีสิทธิ์ข้อมูลบริการห้องพยาบาล');showDrawer('บันทึกบริการห้องพยาบาล',`<p class="form-note" style="margin-bottom:20px">บันทึกบริการนี้แยกจากการจ่ายยา หากใช้เวชภัณฑ์ให้บันทึกการใช้เพื่ออัปเดตสต็อก</p><form id="visit-form"><div class="form-error" role="alert" tabindex="-1"></div><div class="field"><label for="visit-person">ผู้ใช้บริการ</label><input id="visit-person" required placeholder="ชื่อ-นามสกุลผู้ใช้บริการ" maxlength="80"></div><div class="field-grid"><div class="field"><label for="visit-date">วันที่</label><input id="visit-date" type="date" value="${state.asOf}" max="${state.asOf}" required></div><div class="field"><label for="visit-service">ประเภทบริการ</label><select id="visit-service"><option>ปฐมพยาบาล / ทำแผล</option><option>นอนพัก</option><option>ตรวจสัญญาณชีพ</option><option>ส่งต่อ</option><option>บริการอื่น</option></select></div></div><div class="field-grid"><div class="field"><label for="visit-in">เวลาเข้า <small>(ถ้ามี)</small></label><input id="visit-in" type="time"></div><div class="field"><label for="visit-out">เวลาออก <small>(ถ้ามี)</small></label><input id="visit-out" type="time"></div></div><div class="field"><label for="visit-note">อาการ / บันทึกการดูแล</label><textarea id="visit-note" maxlength="500" required placeholder="บันทึกอาการและการดูแลตามจริง"></textarea></div></form>`,`<button class="btn" data-close>ยกเลิก</button><button type="submit" form="visit-form" class="btn primary">บันทึกบริการ</button>`,'OPTIONAL INFIRMARY MODULE');formSave('visit-form',()=>saveAction({action:'visit',createId,date:$('#visit-date').value,person:$('#visit-person').value,service:$('#visit-service').value,timeIn:$('#visit-in').value,timeOut:$('#visit-out').value,note:$('#visit-note').value}),'บันทึกบริการแล้ว');}

function openReadiness(){showDrawer('เกณฑ์ความพร้อมของแต่ละจุด',`<div class="attention-row"><span class="attention-icon">${icon('box')}</span><div class="attention-info"><b>มีของเพียงพอตามเกณฑ์ขั้นต่ำ</b><p>ตั้งขั้นต่ำแยกตามรายการและจุดจัดเก็บ</p></div></div><div class="attention-row"><span class="attention-icon">${icon('calendar')}</span><div class="attention-info"><b>ไม่มีล็อตหมดอายุค้างอยู่</b><p>ของหมดอายุแยกจากยอดพร้อมใช้ และรอตัดจำหน่าย</p></div></div><div class="attention-row"><span class="attention-icon">${icon('checkCircle')}</span><div class="attention-info"><b>ผ่านการตรวจใน 30 วัน</b><p>บันทึกผลตรวจสภาพตู้และของประจำจุด โดยไม่มีปัญหาที่ค้างแก้ไข</p></div></div><p class="form-note" style="margin-top:24px">การตรวจจุดไม่ได้เปลี่ยนยอดสต็อกหรือปิดรายการที่ต้องเติมโดยอัตโนมัติ</p>`,`<button class="btn primary" data-close>เข้าใจแล้ว</button>`);}
function openMore(){showDrawer('เมนูเพิ่มเติม',`<div class="report-options" style="padding:0">${[['reports','chart','รายงาน','สรุปการจ่ายใช้และส่งออกรายงาน'],...(state.company.infirmary&&state.permissions?.canClinical?[['infirmary','heart','บริการห้องพยาบาล','บันทึกและติดตามการให้บริการ']]:[]),['settings','settings','ตั้งค่าการใช้งาน','ส่วนเสริมห้องพยาบาลและเกณฑ์ขั้นต่ำ']].map(([id,ic,title,description])=>`<button class="report-option" data-action="nav:${id}">${icon(ic)}<span><b>${title}</b><p>${description}</p></span>${icon('chevron')}</button>`).join('')}</div>`,`<button class="btn" data-close>ปิด</button>`,'WORKSPACE MENU');}
function openGuide(){showDrawer('ลองใช้งาน First Aid',`<h3 style="margin-bottom:10px">เริ่มจากงานที่ทำจริง</h3><div class="attention-row"><div class="attention-info"><b>01 · บันทึกการใช้</b><p>เลือกจุด รายการ และจำนวน ระบบจ่ายตามล็อต FEFO</p></div></div><div class="attention-row"><div class="attention-info"><b>02 · เติมตู้จากสต็อกสำรอง</b><p>เลือกโอนย้าย เพื่อลดต้นทางและเพิ่มปลายทางพร้อมกัน</p></div></div><div class="attention-row"><div class="attention-info"><b>03 · ตรวจจุดปฐมพยาบาล</b><p>เปิดเมนูจุดปฐมพยาบาล แล้วบันทึกผลตรวจ</p></div></div><div class="attention-row"><div class="attention-info"><b>04 · บริษัทที่มีห้องพยาบาล</b><p>เปิดส่วนเสริมได้จากตั้งค่าการใช้งาน</p></div></div><p class="form-note" style="margin-top:20px">สร้างจุดจัดเก็บ เพิ่มทะเบียนยา แล้วรับเข้าตามจำนวนและล็อตจริง<br>ทุกการเบิกบันทึกผู้เกี่ยวข้องและวันหมดอายุบนระบบกลาง<br>กด / เพื่อค้นหาสต็อก และ Escape เพื่อปิดแผง</p>`,`<button class="btn primary" data-close>เข้าใจแล้ว</button>`,'FIRST AID GUIDE');}
function exportCsv(type){let rows;if(type==='stock'){rows=[['จุดปฐมพยาบาล','รายการ','หน่วย','พร้อมใช้','หมดอายุ','รอยืนยันวันหมดอายุ','ขั้นต่ำ']];scopedLocations().forEach(l=>state.thresholds.filter(t=>t.locationId===l.id).forEach(t=>{const i=itemBy(t.itemId);rows.push([l.name,i.name,i.unit,itemBalance(state,i.id,l.id),state.lots.filter(x=>x.locationId===l.id&&x.itemId===i.id&&expiryDays(x.expiry,state.asOf)<0).reduce((a,x)=>a+x.quantity,0),pendingExpiryLots(state,i.id,l.id).reduce((sum,x)=>sum+x.quantity,0),t.min]);}));}else if(type==='history'){rows=[['เอกสาร','วันที่','ประเภท','วิธีบันทึก','รายการ','จุดต้นทาง','จุดปลายทาง','จำนวน','หน่วย','รหัสผู้เบิก','ชื่อผู้เบิก','แผนกผู้เบิก','ผู้รับจริง','เบิกแทน','ผู้บันทึก','การระบุตัวตน','ล็อต / วันหมดอายุ / จำนวน','หมายเหตุ'],...scopedEvents().map(e=>[e.documentId||e.id,e.datePrecision==='month'?e.date.slice(0,7):e.date,kinds[e.kind],e.recordingMode==='self_service'?'ผู้เบิกบันทึกเอง':e.recordingMode==='staff'?'เจ้าหน้าที่บันทึก':'ข้อมูลเดิม',itemBy(e.itemId)?.name,locBy(e.locationId)?.name,locBy(e.destinationId)?.name||'',e.quantity,itemBy(e.itemId)?.unit,e.requester?.code||'',e.requester?.name||'',e.requester?.department||'',e.recipientPerson?.name||e.recipient,e.onBehalf?'ใช่':'',e.recordedBy?.name||'',e.requester?'ระบุด้วยตนเอง':'ไม่ได้ระบุ',e.allocations?.map(l=>`${esc(l.code)} / ${l.expiry} / ${l.quantity}`).join('; ')||'',e.note])];}else{rows=[['วันที่','จุดปฐมพยาบาล','พร้อมใช้','รายการต้องเติม','ล็อตหมดอายุ','หมายเหตุ'],...(state.inspections||[]).filter(i=>scope==='all'||i.locationId===scope).map(i=>[i.date,locBy(i.locationId).name,i.ready?'พร้อมใช้':'ต้องจัดการ',i.lowItems.length,i.expiredLots.length,i.notes])];}const safe=v=>{const s=String(v??'');return '"'+(/^[=+@\-]/.test(s)?"'"+s:s).replaceAll('"','""')+'"';};const csv='\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download=`first-aid-${type}${type==='history'&&state.historyHasMore?'-latest-500':''}-${state.asOf}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast(`ส่งออกรายงาน ${Math.max(0,rows.length-1)} รายการแล้ว`);}
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();const main=$('#main');main.focus();main.scrollIntoView({block:'start'});});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next!==page){page=next;render();}});
window.addEventListener('beforeunload',event=>{if($('#drawer').dataset.pending==='true'||$('#app').dataset.pending==='true'){event.preventDefault();event.returnValue='';}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!page.startsWith('take/')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#drawer').open){e.preventDefault();navigate('inventory');$('#search')?.focus();}});

function formSave(formId,callback,message){
 const form=$('#'+formId);let busy=false;
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const submit=e.submitter;if(submit)submit.disabled=true;
  try{await callback();$('#drawer').close();render();toast(message);}catch(error){pendingForm(error.uncertain===true);if(error.uncertain)error.message='ยังยืนยันผลไม่ได้ ลองส่งคำขอเดิมอีกครั้ง';const box=form.querySelector('.form-error');if(box){box.textContent=error.message;box.focus();}else toast(error.message);busy=false;if(submit){submit.disabled=false;if(error.uncertain)submit.textContent='ลองส่งคำขอเดิมอีกครั้ง';}}
 };
}
function openLocation(id){
 const item=id?locBy(id):null;const createId=id?undefined:crypto.randomUUID();
 showDrawer(item?'แก้ไขจุดปฐมพยาบาล':'เพิ่มจุดปฐมพยาบาล',`<form id="location-form"><div class="form-error" tabindex="-1" role="alert"></div><div class="field"><label for="location-name">ชื่อจุดจัดเก็บ</label><input id="location-name" value="${esc(item?.name||'')}" placeholder="เช่น ตู้ปฐมพยาบาล อาคารผลิต A" maxlength="120" required></div><div class="field"><label for="location-type">ประเภทจุด</label><select id="location-type">${['ตู้ปฐมพยาบาล','กล่องปฐมพยาบาล','กระเป๋าฉุกเฉิน','ห้องพยาบาล','คลังสำรอง'].map(t=>`<option ${item?.type===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label for="location-area">พื้นที่ / ตำแหน่ง</label><input id="location-area" value="${esc(item?.area||'')}" maxlength="200" placeholder="เช่น ชั้น 1 ข้างห้องพักพนักงาน"></div><div class="field"><label for="location-mode">วิธีบันทึกการเบิก</label><select id="location-mode"><option value="controlled" ${item?.issueMode!=='self_service'?'selected':''}>เจ้าหน้าที่บันทึกให้</option><option value="self_service" ${item?.issueMode==='self_service'?'selected':''}>ผู้เบิกบันทึกเอง</option></select></div><p class="form-note">สร้างจุดแล้วรับเข้าตามยอดจริง และกำหนดรายการขั้นต่ำให้เหมาะกับพื้นที่</p></form>`,`<button class="btn" data-close>ยกเลิก</button><button type="submit" form="location-form" class="btn primary">บันทึกจุด</button>`,'CARE POINT');
 formSave('location-form',()=>saveAction({action:'location',...(id?{id}:{createId}),name:$('#location-name').value,type:$('#location-type').value,area:$('#location-area').value,issueMode:$('#location-mode').value}),'บันทึกจุดปฐมพยาบาลแล้ว');
}
function openItem(id){
 const item=id?itemBy(id):null;const createId=id?undefined:crypto.randomUUID();
 showDrawer(item?'แก้ไขทะเบียนรายการ':'เพิ่มยาและเวชภัณฑ์',`<form id="item-form"><div class="form-error" tabindex="-1" role="alert"></div><div class="field"><label for="item-name">ชื่อยา / เวชภัณฑ์</label><input id="item-name" value="${esc(item?.name||'')}" maxlength="160" placeholder="ชื่อรายการตามบรรจุภัณฑ์" required></div><div class="field"><label for="item-generic">รายละเอียด / ขนาด <small>(ถ้ามี)</small></label><input id="item-generic" value="${esc(item?.generic||'')}" maxlength="250" placeholder="ชื่อไทย ขนาด หรือรูปแบบบรรจุ"></div><div class="field-grid"><div class="field"><label for="item-category">หมวดหมู่</label><select id="item-category">${['ยา','เวชภัณฑ์','อุปกรณ์'].map(t=>`<option ${item?.category===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label for="item-unit">หน่วยนับพื้นฐาน</label><input id="item-unit" value="${esc(item?.unit||'')}" maxlength="40" placeholder="เช่น เม็ด ซอง ขวด" required></div></div><div class="field"><label for="item-min">ขั้นต่ำเริ่มต้นต่อจุด</label><input id="item-min" type="number" min="0" step="1" value="${item?.min||0}" required><small class="hint">ปรับเฉพาะแต่ละจุดได้ในตั้งค่าเกณฑ์ขั้นต่ำ</small></div><label class="on-behalf"><input id="item-expiry" type="checkbox" ${item?.trackExpiry!==false?'checked':''}>ติดตามวันหมดอายุแยกตามล็อต</label><p class="form-note">ใช้หน่วยนับเดียวกันในการรับเข้าและจ่ายใช้ เพื่อให้ยอดตรงกับที่ตรวจนับจริง</p></form>`,`<button class="btn" data-close>ยกเลิก</button><button type="submit" form="item-form" class="btn primary">บันทึกรายการ</button>`,'ITEM REGISTER');
 formSave('item-form',()=>saveAction({action:'item',...(id?{id}:{createId}),name:$('#item-name').value,generic:$('#item-generic').value,category:$('#item-category').value,unit:$('#item-unit').value,min:Number($('#item-min').value),trackExpiry:$('#item-expiry').checked}),'บันทึกทะเบียนรายการแล้ว');
}
function openPointLink(id){
 const point=locBy(id);if(!point)return;
 showDrawer('ลิงก์และ QR ประจำจุด',`<div class="point-settings-title">${itemIcon(point)}<div><h3>${esc(point.name)}</h3><p>ผู้เบิกหยิบใช้แล้วลงรายการเอง</p></div></div><div id="point-link-result"><p class="form-note">${point.hasPublicLink?'จุดนี้เคยสร้างลิงก์แล้ว หากสร้างใหม่ ลิงก์และ QR เดิมจะใช้ไม่ได้ กรุณาเปลี่ยนป้ายที่จุดจัดเก็บด้วย':'สร้างลิงก์เฉพาะจุดนี้สำหรับพนักงานบันทึกการหยิบใช้ ไม่แสดงประวัติผู้อื่นหรือทะเบียนพนักงาน'}</p><button class="btn primary" id="create-point-link" style="margin-top:20px">${icon('cross')}${point.hasPublicLink?'สร้างลิงก์ใหม่แทนเดิม':'สร้างลิงก์และ QR'}</button></div>`,`<button class="btn" data-close>ปิด</button>`,'SELF SERVICE LINK');
 $('#create-point-link').onclick=async e=>{
  e.target.disabled=true;
  try{const result=await api('/api/first-aid/manage'+companyQuery,{action:'rotate-token',locationId:id});try{await refresh();}catch{staleData=true;}const url=new URL(result.url,location.origin);if(url.origin!==location.origin)throw new Error('ที่อยู่ลิงก์ไม่ถูกต้อง');const qr='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(result.qrSvg);
   $('#point-link-result').innerHTML=`<div class="point-qr"><img src="${qr}" alt="QR บันทึกการหยิบใช้ ${esc(point.name)}"><b>${esc(point.name)}</b><p>สแกนเพื่อบันทึกของที่หยิบใช้</p></div><label class="field"><span class="small">ลิงก์ประจำจุด</span><input id="point-share-url" value="${esc(url.href)}" readonly></label><div class="heading-actions" style="flex-wrap:wrap;margin-top:15px"><a class="btn primary" href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">เปิดหน้าผู้เบิก ${icon('arrow')}</a><button class="btn" id="copy-point-link">คัดลอกลิงก์</button><a class="btn" download="first-aid-qr.svg" href="${qr}">ดาวน์โหลด QR</a></div><p class="form-note" style="margin-top:18px">ลิงก์นี้ใช้บันทึกการเบิกเฉพาะจุด โปรดแจกหรือแสดงไว้ภายในพื้นที่ที่อนุญาต</p>`;
   $('#copy-point-link').onclick=async()=>{try{await navigator.clipboard.writeText(url.href);toast('คัดลอกลิงก์แล้ว');}catch{$('#point-share-url').focus();$('#point-share-url').select();toast('เลือกลิงก์แล้ว สามารถคัดลอกได้');}};
  }catch(error){e.target.disabled=false;toast(error.message);}
 };
}
async function boot(){
 $('#app').innerHTML='<div class="boot-state"><div class="boot-symbol">+</div><h1>First Aid & Medicine Control</h1><p>กำลังโหลดข้อมูลบริษัท…</p></div>';
 try{await refresh();if(publicToken)page='take/'+state.locations[0]?.id;render();}
 catch(error){$('#app').innerHTML=`<div class="boot-state"><div class="boot-symbol">+</div><h1>ยังเปิดข้อมูลไม่ได้</h1><p>${esc(error.message)}</p><button class="btn primary" id="boot-retry">ลองใหม่</button>${!publicToken?'<a class="btn" href="/first-aid" target="_top">เข้าสู่ระบบ / เลือกบริษัท</a>':''}</div>`;$('#boot-retry').onclick=boot;}
}

boot();
